import java.util.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;
import com.koios.game.arpg.*;import com.koios.game.model.item.Item;
public final class BaseBalanceCheck {
 static int checks;static void check(boolean ok,String msg){checks++;if(!ok)throw new AssertionError(msg);}
 static double dps(Item item,int level,int tier){Map<Stat,Double>s=ArpgStats.equipment(new Item[]{item},level);return (s.get(Stat.PHYSICAL_MIN)+s.get(Stat.PHYSICAL_MAX))/2*s.get(Stat.ATTACK_SPEED)*(1+s.get(Stat.CRITICAL_CHANCE)/100*(s.get(Stat.CRITICAL_MULTIPLIER)/100-1))*Defences.hitChance(s.get(Stat.ACCURACY),4*tier);}
 public static void main(String[]args)throws Exception{
 PrototypeIntegrationCheck.loaded();StringBuilder report=new StringBuilder("# Base balance reference\n\nExpected basic-attack sustained DPS using production stat aggregation, average physical roll, attack speed, critical expectation, and hitChance versus map defence (2*tier defence, doubled for evasion). No passives/supports/skill cooldowns, enemy attacks, armour on NPCs, travel, overkill, affix identification delays or damage map mods. Character and item level=2*tier; unavailable bases are evaluated at their minLevel and flagged LOCKED. Rare median/P90 use 1,000 deterministic catalog rolls per row; P90 is damage quality, not a guaranteed drop. Boss HP=120+35*tier; normal HP=22+8*tier. HP/DPS is expected sustained kill time, not a discrete first-hit simulation.\n\n|Base|Tier|Level|Access|Normal DPS|Rare median|Rare P90|Normal mob sec|Normal boss sec|Rare median boss sec|\n|---|---:|---:|---|---:|---:|---:|---:|---:|---:|\n");
 Set<Integer>ids=new HashSet<>();for(EquipmentBases.Base base:EquipmentBases.all()){check(ids.add(base.itemId),"Unique base ID");if(base.itemId>=22435){check(base.minLevel>=8,"New base level gate");for(int l=1;l<base.minLevel;l++)for(int n=0;n<30;n++)check(EquipmentBases.select(base.weapon,new Random(l*97+n),l).itemId!=base.itemId,"New base excluded below its gate");}if(!base.weapon)continue;
 for(int tier=1;tier<=6;tier++){int level=Math.max(tier*2,base.minLevel);Item item=EquipmentBases.create(base,level);double normal=dps(item,level,tier);double[]rare=new double[1000];Random rng=new Random(1543+base.itemId*31+tier);for(int sample=0;sample<rare.length;sample++){Item roll=EquipmentBases.create(base,level);roll.setRoll(roll.getRoll().changed(ItemRoll.Rarity.RARE,true,0,AffixCatalog.roll(roll,ItemRoll.Rarity.RARE,rng),null));rare[sample]=dps(roll,level,tier);check(Double.isFinite(rare[sample])&&rare[sample]>=normal,"Rare affixes never reduce expected damage");}Arrays.sort(rare);check(normal>0,"Positive base DPS");report.append(String.format(Locale.ROOT,"|%s|%d|%d|%s|%.2f|%.2f|%.2f|%.2f|%.2f|%.2f|%n",base.name,tier,level,tier*2<base.minLevel?"LOCKED":"Open",normal,rare[500],rare[900],(22+8*tier)/normal,(120+35*tier)/normal,(120+35*tier)/rare[500]));}}
 Path out=Paths.get("../../logs/base-balance.md");Files.write(out,report.toString().getBytes(StandardCharsets.UTF_8));System.out.println("Passed "+checks+" base balance checks; wrote "+out+".");
 }
}
